const items = $input.all();

function trim(v) {
  return String(v ?? '').trim();
}

function normalizePhone(v) {
  const raw = trim(v).replace(/[^\d+]/g, '');
  if (!raw) return '';
  const canonical = raw.startsWith('+62') ? `62${raw.slice(3)}` : raw;
  return canonical.startsWith('0') ? `62${canonical.slice(1)}` : canonical;
}

return items.map((item) => {
  // Webhook n8n (v2) membungkus body POST di item.json.body. Fallback ke root.
  const payload = (item.json && item.json.body) ? item.json.body : (item.json || {});
  // Generik: terima `to` (PpdbWhatsappNotifier) ATAU `target` (modul Notifikasi/WaGatewayService).
  const to = normalizePhone(payload.to || payload.target);
  const message = trim(payload.message);

  // Lampiran opsional: { data(base64) | url, mimetype, filename }. Bila ada,
  // pesan dikirim sebagai media (sendImage/sendFile) dgn caption = message.
  const f = (payload.file && typeof payload.file === 'object') ? payload.file : null;
  const file = (f && (f.data || f.url)) ? {
    data: f.data ? String(f.data) : null,
    url: f.url ? String(f.url) : null,
    mimetype: trim(f.mimetype) || 'application/octet-stream',
    filename: trim(f.filename) || 'lampiran'
  } : null;

  if (!to) throw new Error('Payload invalid: field "to"/"target" wajib diisi.');
  if (!message && !file) throw new Error('Payload invalid: "message" atau "file" wajib diisi.');

  return {
    json: {
      to,
      chatId: `${to}@c.us`,
      message,
      file,
      eticket_no: trim(payload.eticket_no) || null,
      student_name: trim(payload.student_name) || null,
      template_code: trim(payload.template_code) || null,
      source: trim(payload.source) || 'ppdb_register',
      received_at: new Date().toISOString()
    }
  };
});

const items = $input.all();

const endpointBase = String($env.N8N_WAHA_BASE_URL || 'http://waha:3000').trim().replace(/\/+$/, '');
const token = String($env.N8N_WAHA_API_KEY || '').trim();
const session = String($env.N8N_WAHA_SESSION || 'default').trim() || 'default';

const out = [];
for (const { json } of items) {
  // Tanpa file -> sendText. Ada file -> sendImage (gambar) / sendFile (lainnya).
  let url = `${endpointBase}/api/sendText`;
  let body = { session, chatId: json.chatId, text: json.message };
  if (json.file && (json.file.data || json.file.url)) {
    const isImage = String(json.file.mimetype || '').startsWith('image/');
    url = `${endpointBase}/api/${isImage ? 'sendImage' : 'sendFile'}`;
    const fileObj = { mimetype: json.file.mimetype, filename: json.file.filename };
    if (json.file.data) fileObj.data = json.file.data; else fileObj.url = json.file.url;
    body = { session, chatId: json.chatId, file: fileObj, caption: json.message || '' };
  }
  // Jangan ikutkan file (base64) ke output -> hemat penyimpanan eksekusi.
  const base = { to: json.to, chatId: json.chatId, message: json.message, eticket_no: json.eticket_no, student_name: json.student_name, template_code: json.template_code, source: json.source, received_at: json.received_at };
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url,
      headers: token ? { 'X-Api-Key': token } : {},
      body,
      json: true,
      returnFullResponse: true,
    });
    const bodyStr = typeof response.body === 'string' ? response.body : JSON.stringify(response.body);
    out.push({ json: { ...base, sent: true, provider: 'waha', reason: 'sent', gateway_status: response.statusCode, gateway_response: bodyStr ? bodyStr.slice(0, 500) : null } });
  } catch (error) {
    const status = error.statusCode || error.httpCode || 0;
    out.push({ json: { ...base, sent: false, provider: 'waha', reason: status ? `http_${status}` : 'request_error', gateway_status: status, gateway_response: String(error?.message || error || 'unknown_error').slice(0, 500) } });
  }
}

return out;
